# Кронштейн под трубу Ø108 на стене — компоновка по наброску конструктора от руки
# (attachments/20261021-0743-nabrosok-kronshteyna.png). Детали, генератор и варианты — после согласования компоновки.
id: sketch_pilot
title: "Кронштейн под трубу Ø108 на стене"
description: >
  Опорная плита на четырёх анкерах M16 в стене, два ребра (сужаются от плиты к трубе) и ложемент под трубу Ø108
  с вылетом оси 500 от стены. На трубу действует вертикальная нагрузка Fv = 20 кН.
lang: ru
coordinate_system: "X — вдоль стены (по оси трубы), Y — от стены, Z — вверх; Y=0 — лицевая плоскость стены, Z=0 — ось трубы"
standards: [gost]

requirements:
  purpose: "Опора горизонтальной трубы Ø108 на стене: труба лежит на кронштейне, вылет оси от стены 500"
  loads: {Fv: 20, Fh: 0, Fa: 0}          # кН: вниз (с наброска); от стены и вдоль трубы — на наброске не показаны, см. G2
  factors: {gamma_dyn: 1.0}
  safety_required: 1.5
  environment: {location: "помещение", wall: "бетон B25, толщина ≥ 250 мм"}

skeleton:
  datums:
    - {id: wall, kind: plane, origin: [0, 0, 0], direction: [0, 1, 0], name: "Лицевая плоскость стены"}
    - {id: pipe_axis, kind: axis, origin: [0, 500, 0], direction: [1, 0, 0], name: "Ось трубы (вылет 500 от стены)"}
  envelopes:
    # отведённый объём кронштейна: по высоте — плита 300 (с наброска), по ширине — оценка, по вылету — до трубы
    - {id: place, kind: keep_in, min: [-100, 0, -150], max: [100, 500, 150], name: "Габарит кронштейна (ширина 200 — оценка)"}
  interfaces:
    - id: wall
      kind: mount_plane
      name: "Крепление к стене: плита s=12, 4 анкера M16"
      datum: wall
      params: {concrete: B25, anchor_size: M16, count: 4, plate_thickness: 12, plate_height: 300}
    - id: pipe
      kind: pipe_rest
      name: "Опирание трубы Ø108"
      datum: pipe_axis
      params: {od: 108, length: 200, lateral_gap: 3}   # наружный диаметр с наброска; длина ложемента вдоль трубы — оценка
  # обстановка: тела вокруг изделия — на компоновочном эскизе и в проверках (деталь не должна врезаться)
  surroundings:
    - {id: wall_body, kind: plane, role: wall, name: "Стена", material: "бетон B25", origin: [0, 0, 0], normal: [0, 1, 0], extent: 450, thickness: 250}
    - {id: pipe_body, kind: cylinder, role: pipe, name: "Труба Ø108×6", material: "сталь", origin: [0, 500, 0], axis: [1, 0, 0], d: 108, length: 600}

params: {}

assumptions:
  - {id: G1, topic: sketch, text: "Прочитано с наброска: стена слева (штриховка); плита s=12 высотой 300 на стене; 4 анкера M16 (в боковом виде — два ряда); два ребра от плиты к трубе; труба Ø108, ось на 500 от стены; Fv = 20 кН вниз на трубу."}
  - {id: G2, topic: loads, text: "На наброске показана только вертикальная сила Fv = 20 кН. Горизонтальные составляющие (вдоль трубы от трения/теплового удлинения, от стены) не показаны — приняты 0; динамика не учтена (γd = 1,0). Подтвердить."}
  - {id: G3, topic: geom, text: "Ось трубы — на уровне середины плиты (на наброске центр трубы и середина плиты совпадают с точностью ~15 мм): плита от Z = −150 до +150."}
  - {id: G4, topic: geom, text: "Ширина плиты вдоль трубы (X) на наброске не видна — принято 200 (≈ 2 диаметра трубы); анкеры 2×2 с шагом 120 по X и 220 по Z (по пропорциям наброска: отверстия на ~40 от верхней и нижней кромок плиты)."}
  - {id: G5, topic: geom, text: "Рёбра на наброске сужаются от плиты к трубе: высота у стены ≈ 220, у трубы ≈ 140 (по пропорциям); ложемент охватывает трубу снизу, без хомута — труба свободно лежит. Длина ложемента вдоль трубы 200 — оценка."}
  - {id: G6, topic: wall, text: "Материал стены на наброске не подписан: принят бетон B25, толщина ≥ 250 (глубина анкера M16 по каталогу gost hef = 125), край стены далеко (c > c_min = 80)."}
  - {id: G7, topic: pipe, text: "Толщина стенки трубы не подписана: принята 108×6 по сортаменту пакета gost (ближайший размер); среда в трубе неизвестна, вес уже учтён в Fv."}
  - {id: G8, topic: anchors, text: "Анкеры химические M16 (по подписи «4 анкера M16»); несущая способность по бетону — условная из каталога пилота (N_Rd = 20 кН, V_Rd = 15 кН), заменить данными производителя."}
  - {id: G9, topic: material, text: "Материал кронштейна Ст3сп (С245), эксплуатация в помещении — на наброске не указано."}

